solution.solution.cpp:
#include <stdexcept>
#include <string>
#include <string_view>
#include <vector>

namespace
{
    bool isSpace(char c)
    {
        return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v';
    }
}

std::vector<std::string> splitWhitespace(std::string_view s, int maxSplit = -1)
{
    std::vector<std::string> out;
    std::size_t i{ 0 };
    int splits{ 0 };
    for (;;)
    {
        while (i < s.size() && isSpace(s[i])) ++i;
        if (i == s.size()) break;
        if (maxSplit >= 0 && splits == maxSplit)
        {
            out.emplace_back(s.substr(i));
            break;
        }
        std::size_t j{ i };
        while (j < s.size() && !isSpace(s[j])) ++j;
        out.emplace_back(s.substr(i, j - i));
        i = j;
        ++splits;
    }
    return out;
}

std::vector<std::string> split(std::string_view s, std::string_view sep, int maxSplit = -1)
{
    if (sep.empty()) throw std::invalid_argument("split: empty separator");
    std::vector<std::string> out;
    std::size_t start{ 0 };
    int splits{ 0 };
    while (maxSplit < 0 || splits < maxSplit)
    {
        const std::size_t at{ s.find(sep, start) };
        if (at == std::string_view::npos) break;
        out.emplace_back(s.substr(start, at - start));
        start = at + sep.size();
        ++splits;
    }
    out.emplace_back(s.substr(start));
    return out;
}

std::string join(const std::vector<std::string>& parts, std::string_view sep)
{
    std::string out;
    for (std::size_t i{ 0 }; i < parts.size(); ++i)
    {
        if (i > 0) out += sep;
        out += parts[i];
    }
    return out;
}

std::string replaceAll(std::string_view s, std::string_view from, std::string_view to, int maxCount = -1)
{
    std::string out;
    int done{ 0 };
    const auto allowed{ [&] { return maxCount < 0 || done < maxCount; } };
    if (from.empty())
    {
        for (std::size_t i{ 0 }; i <= s.size(); ++i)
        {
            if (allowed()) { out += to; ++done; }
            if (i < s.size()) out += s[i];
        }
        return out;
    }
    std::size_t start{ 0 };
    while (allowed())
    {
        const std::size_t at{ s.find(from, start) };
        if (at == std::string_view::npos) break;
        out += s.substr(start, at - start);
        out += to;
        start = at + from.size();
        ++done;
    }
    out += s.substr(start);
    return out;
}

bool startsWith(std::string_view s, std::string_view prefix, std::size_t start = 0)
{
    if (start > s.size()) return false;
    return s.substr(start).starts_with(prefix);
}

std::vector<std::string> splitLines(std::string_view s, bool keepEnds = false)
{
    std::vector<std::string> out;
    std::size_t i{ 0 };
    while (i < s.size())
    {
        std::size_t j{ i };
        while (j < s.size() && s[j] != '\n' && s[j] != '\r') ++j;
        if (j == s.size())
        {
            out.emplace_back(s.substr(i));
            break;
        }
        const std::size_t end{ (s[j] == '\r' && j + 1 < s.size() && s[j + 1] == '\n') ? 2u : 1u };
        out.emplace_back(s.substr(i, j - i + (keepEnds ? end : 0)));
        i = j + end;
    }
    return out;
}

unitTests:
using Strings = std::vector<std::string>;
TEST("splitting on whitespace") {
    CHECK(splitWhitespace("  the quick\tbrown\n fox ") == (Strings{ "the", "quick", "brown", "fox" }));
    CHECK(splitWhitespace("one") == (Strings{ "one" }));
    CHECK(splitWhitespace("").empty());
    CHECK(splitWhitespace(" \t\r\n\f\v ").empty());
}
TEST("whitespace with a limit") {
    CHECK(splitWhitespace("  a  b  c  ", 1) == (Strings{ "a", "b  c  " }));
    CHECK(splitWhitespace("  a  b  c  ", 0) == (Strings{ "a  b  c  " }));
    CHECK(splitWhitespace("a b c", 2) == (Strings{ "a", "b", "c" }));
    CHECK(splitWhitespace("a b c", 5) == (Strings{ "a", "b", "c" }));
    CHECK(splitWhitespace("a   ", 1) == (Strings{ "a" }));
    CHECK(splitWhitespace("   ", 0).empty());
}
TEST("splitting on a separator") {
    CHECK(split("a,b,c", ",") == (Strings{ "a", "b", "c" }));
    CHECK(split("a,,b", ",") == (Strings{ "a", "", "b" }));
    CHECK(split(",a,", ",") == (Strings{ "", "a", "" }));
    CHECK(split("", ",") == (Strings{ "" }));
    CHECK(split("a::b::c", "::") == (Strings{ "a", "b", "c" }));
    CHECK(split("no separator", ";") == (Strings{ "no separator" }));
}
TEST("a separator with a limit, and an empty one") {
    CHECK(split("a,b,c,d", ",", 2) == (Strings{ "a", "b", "c,d" }));
    CHECK(split("a,b", ",", 0) == (Strings{ "a,b" }));
    CHECK(split("a,b", ",", 9) == (Strings{ "a", "b" }));
    CHECK_THROWS_AS(split("abc", ""), std::invalid_argument);
}
TEST("joining") {
    CHECK_EQ(join({ "a", "b", "c" }, ", "), std::string("a, b, c"));
    CHECK_EQ(join({ "solo" }, "-"), std::string("solo"));
    CHECK_EQ(join({}, "-"), std::string(""));
    CHECK_EQ(join({ "", "" }, "+"), std::string("+"));
    CHECK_EQ(join(split("x,y,,z", ","), ","), std::string("x,y,,z"));
}
TEST("replacing") {
    CHECK_EQ(replaceAll("one two one", "one", "1"), std::string("1 two 1"));
    CHECK_EQ(replaceAll("aaaa", "aa", "b"), std::string("bb"));
    CHECK_EQ(replaceAll("aaa", "aa", "b"), std::string("ba"));
    CHECK_EQ(replaceAll("one one one", "one", "1", 2), std::string("1 1 one"));
    CHECK_EQ(replaceAll("abc", "b", "", 0), std::string("abc"));
    CHECK_EQ(replaceAll("abc", "x", "y"), std::string("abc"));
    CHECK_EQ(replaceAll("a.b.c", ".", ".."), std::string("a..b..c"));
}
TEST("replacing an empty string") {
    CHECK_EQ(replaceAll("abc", "", "-"), std::string("-a-b-c-"));
    CHECK_EQ(replaceAll("abc", "", "-", 2), std::string("-a-bc"));
    CHECK_EQ(replaceAll("", "", "x"), std::string("x"));
    CHECK_EQ(replaceAll("ab", "", "-", 0), std::string("ab"));
}
TEST("prefixes from a position") {
    CHECK(startsWith("documentation", "doc"));
    CHECK(!startsWith("documentation", "Doc"));
    CHECK(startsWith("documentation", "ument", 3));
    CHECK(startsWith("abc", "", 0));
    CHECK(startsWith("abc", "", 3));
    CHECK(!startsWith("abc", "", 4));
    CHECK(!startsWith("abc", "c", 3));
    CHECK(!startsWith("ab", "abc"));
}
TEST("splitting lines") {
    CHECK(splitLines("a\n\nb\r\nc\r") == (Strings{ "a", "", "b", "c" }));
    CHECK(splitLines("a\n\nb\r\nc\r", true) == (Strings{ "a\n", "\n", "b\r\n", "c\r" }));
    CHECK(splitLines("one line") == (Strings{ "one line" }));
    CHECK(splitLines("ends\n") == (Strings{ "ends" }));
    CHECK(splitLines("").empty());
    CHECK(splitLines("\n") == (Strings{ "" }));
    CHECK(splitLines("\r\r\n") == (Strings{ "", "" }));
    CHECK(splitLines("x\n\r") == (Strings{ "x", "" }));
}

